  const O = 'stroke="#232323" stroke-width="3.2" stroke-linejoin="round" stroke-linecap="round"';
  const HL = 'fill="none" stroke="#fff" stroke-linecap="round" opacity=".75"';   // 高光线

  const g = (id, a, b) => `<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
  const DEFS = `<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>
    ${g("plat", "#f6f6f3", "#cdcdc7")}${g("platD", "#c2c2bc", "#8e8e88")}${g("scr", "#93b3f3", "#4b70d4")}
    ${g("red", "#ff7a6b", "#d33a2e")}${g("cream", "#fffdf7", "#eee5d0")}${g("fold", "#a6c5f8", "#6b93e4")}${g("foldF", "#c3dafc", "#82a8ef")}
    ${g("vio", "#b597f7", "#6b42d6")}${g("sea", "#86ccff", "#2f7fe0")}${g("land", "#9ae692", "#3fae58")}${g("pink", "#ffdbe8", "#f19bbb")}
    ${g("teal", "#9eeccf", "#36ad86")}${g("sky", "#9fd2ff", "#e3f2ff")}${g("sun", "#ffe27a", "#ffb627")}${g("gold", "#ffd95e", "#f2a91c")}
    ${g("orange", "#ffc66b", "#f08a24")}${g("coral", "#ffb08a", "#ef5f3a")}${g("paper", "#ffffff", "#e6ebf2")}
    ${g("tv", "#ff8a3d", "#b34ce8")}${g("ig", "#ffce5c", "#c13584")}
    <pattern id="scan" width="4" height="3" patternUnits="userSpaceOnUse"><rect width="4" height="1" fill="rgba(25,45,130,.16)"/></pattern>
    <filter id="sh" x="-20%" y="-20%" width="140%" height="150%"><feDropShadow dx="0" dy="2.5" stdDeviation="2" flood-color="#000" flood-opacity=".22"/></filter>
  </defs></svg>`;

  const gearPath = (cx, cy, ro, ri, n) => {
    const h = Math.PI / n, p = [];
    for (let i = 0; i < n; i++) {
      const a = i * 2 * h - Math.PI / 2;
      [[ri, a - h * .62], [ro, a - h * .36], [ro, a + h * .36], [ri, a + h * .62]]
        .forEach(([r, t]) => p.push((cx + r * Math.cos(t)).toFixed(1) + "," + (cy + r * Math.sin(t)).toFixed(1)));
    }
    return "M" + p.join(" L") + "Z";
  };

